
namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokKontChodResultTab extends GContentBase {

        private grid: JQuery<HTMLElement>;
        private data;

        onContentReady() {

            var that = this;

            this.grid =
                $("<div>").appendTo(this.element)
                .ggrid({
                    data: this.data,   // this.modelPolozky[0]   //zatim nemam zadna data, nastavim prazdne pole. V momente nacteni je nastavim pres options (metoda loadJsGrid)
                        renderMode: "auto",     // auto, all-at-once, paged-sync, paged-async
                        columnMode: "fit",      // fit, full
                        navigationMode: "row", // row, cell
                        rowNumbers: false,
                        columns: new Gordic.Data.GridFormat()
                            .addNumberColumn(
                                {
                                    name: "cislo_radku",
                                    caption: "#",
                                    sortable: false,
                                    width: 20                                    
                                })
                            .addSortedEkoCfuSet(this, true)
                            .addTextColumn({
                                name: "nks",
                                caption: "jres:31302118", //RC 31302118 : NKS
                                sortable: false
                            })
                            .addNumberColumn({
                                name: "c0",
                                caption: "jres:31302500", //RC 31302500 : MD
                                sortable: false,
                            })
                            .addNumberColumn({
                                name: "c1",
                                caption: "jres:31302499", //RC 31302499 : Dal
                                sortable: false,
                            })
                            .addTextColumn({
                                name: "txt_err",
                                caption: "jres:31302322", //RC 31302322 : Popis chyby
                                sortable: false,
                                width: 300
                            })
                    });

        }
}
}

        



